function jwtPayload(token) {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('invalid token');
  const b64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');
  const padded = b64 + '='.repeat((4 - (b64.length % 4)) % 4);
  const json = Buffer.from(padded, 'base64').toString('utf8');
  return JSON.parse(json);
}
```

This only decodes. Never trust claims from an unverified JWT. In browsers, replace `Buffer` with `atob` plus `decodeURIComponent` for Unicode.

```ts
type Json = null | boolean | number | string | Json[] | { [k: string]: Json };

export function deepMerge(a: Json, b: Json): Json {
  if (Array.isArray(a) && Array.isArray(b)) return [...a, ...b];
  if (isObj(a) && isObj(b)) {
    const out: { [k: string]: Json } = { ...a };
    for (const [k, v] of Object.entries(b)) {
      out[k] = k in out ? deepMerge(out[k], v) : v;
    }
    return out;
  }
  return b;
}

function isObj(x: Json): x is { [k: string]: Json } {
  return typeof x === "object" && x !== null && !Array.isArray(x);
}
```

Primitives and mismatched types take `b`.

